---更新home数据
---@param activityId integer 活动Id
function ActivityNightCatMgr:UpdateHomeData(activityId)
    if not activityId then return end
    
    GameUtils.Request(Interfaces.ActivityNightCatHome, {activityUuid = activityId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        
        if response.data.startTime then
            response.data.startTime = checkInt(response.data.startTime) + os.time()
        end
        if response.data.endTime then
            response.data.endTime = checkInt(response.data.endTime) + os.time()
        end
        self:SetActivityId(activityId)
        self:GetNightCatComponent():Initial(response.data)
        self:GetNightCatQuestComponent():Initial(activityId, response.data)
        local chapterData = self:ConvertChapterData()
        self:GetNightCatComponent():SetChapterData(chapterData)

        Events.Broadcast(Constants.EventNames.ActivityNightCatHomeDataUpdate)
    end)
end

function ActivityNightCatMgr:DrawRewardsReq(cb)
    GameUtils.Request(Interfaces.ActivityNightCatPassReward, {activityUuid = self:GetActivityId()}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end

        GoodsUtils.DrawRewards(response.data.rewards)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = response.data.rewards}})
        self:ReceiveClearRewards()
        if cb then
            cb()
        end
    end)
end

---更新章节数据
function ActivityNightCatMgr:UpdateChapterData()
    local chapterData = self:ConvertChapterData()
    self:GetNightCatComponent():SetChapterData(chapterData)
end

---转换章节数据
function ActivityNightCatMgr:ConvertChapterData()
    local comp = self:GetNightCatComponent()
    local chapterData = {}
    local questChapterVo = CfUtils.GetCf(AutoIds.IdSetting2735, "NightCatQuestChapterVo", true)
    for _, v in ipairs(questChapterVo) do
        if v.activetyId == comp:GetScheduleId() then
            v.state = self:GetChapterState(v.id)
            local dojo = ActivityNightCatChapterDojo.New()
            dojo:Fill(v)
            chapterData[tostring(v.id)] = dojo
        end
    end
    return chapterData
end

---获取章节解锁状态
---@param chapterId integer 章节id
function ActivityNightCatMgr:GetChapterState(chapterId)

    -- 爬塔层数
    local nowFloor = self._nightCatQuestComponent:GetMaxPassTowerId()
    if nowFloor == 0 then
        return ActivityNightCatConstants.ChapterState.LOCK
    end

    -- 通过的主线关卡
    local questId = self:GetPlotInfoByChapterId(chapterId)
    if questId == 0 then
        local unlockChapter = CfUtils.GetCf(AutoIds.IdSetting2735, "NightCatQuestChapterVo"):Get(chapterId).unlockChapter
        unlockChapter = parse_strings(unlockChapter, ";")
        local isLocked = false
        for i, v in ipairs(unlockChapter) do
            if checkInt(v) ~= 0 then
                if not self:JudgeChapterFinished(v) then
                    isLocked = true
                    break
                end
            end
        end
        return isLocked and ActivityNightCatConstants.ChapterState.LOCK or ActivityNightCatConstants.ChapterState.UNLOCK
    else
        return self:JudgeChapterFinished(chapterId) and ActivityNightCatConstants.ChapterState.FINISH or ActivityNightCatConstants.ChapterState.UNLOCK
    end
end

---判断章节是否完成
---@param chapterId integer 章节id
---@return boolean 是否完成章节
function ActivityNightCatMgr:JudgeChapterFinished(chapterId)
    local comp = self:GetNightCatComponent()
    local plotVo = CfUtils.GetCf(AutoIds.IdSetting2733, "NightCatPlotVo", true)
    local isFinished = true
    local questId = self:GetPlotInfoByChapterId(chapterId)
    if checkInt(questId) == 0 then return false end
    
    local plotId = self:GetPlotIdByQuestId(questId)
    for _, v in ipairs(plotVo) do
        if v.activetyId == comp:GetScheduleId() and v.chapter == checkInt(chapterId) then
            if plotId == checkInt(v.unlockPlot) then
                isFinished = false
                break
            end
        end
    end
    return isFinished
end

---判断最终奖励是否解锁
---@return boolean
function ActivityNightCatMgr:JudgeClearRewardUnlock()
    local chapterData = self:GetChapterData()
    local isUnlock = true
    for id, v in pairs(chapterData) do
        if v.state ~= ActivityNightCatConstants.ChapterState.FINISH then
            isUnlock = false
            break
        end
    end
    return isUnlock
end

---进入关卡
---@param id integer 关卡id
function ActivityNightCatMgr:EnterQuest(id, startCB, endCB)
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(id)
    if not vo then
        return
    end

    if checkInt(vo.type) == Constants.QuestBattleType.Story then
        -- 处理剧情
        if startCB then
            startCB()
        end
        self:PlayPlot(vo, function()
            if endCB then
                endCB()
            end
            GameUtils.Request(Interfaces.ActivityNightCatPlotQuest, {activityUuid = self:GetActivityId(), questId = id}, function (request, response)
                if checkNumber(response.errCode) ~= 0 then return end
                local plotId = self:GetPlotIdByQuestId(id)
                local comp = self:GetNightCatComponent()
                local clearChapter, unlockChapters = self:GetQuestClearUnlockChapter(id)
                comp:AddFinishPlot(plotId)
                self:UpdateChapterData()
                Events.Broadcast(Constants.EventNames.ActivityNightCatChapterDataUpdate, {questId = id, clearChapter = clearChapter, unlockChapters = unlockChapters})
            
                local nightCatQuestComp = self:GetNightCatQuestComponent()
                nightCatQuestComp:RefreshBuff(response.data)
            end)
        end)
    else
        local activityId = self:GetActivityId()
        local clearChapter, unlockChapters = self:GetQuestClearUnlockChapter(id)
        CS.Engine.UI.UIModule.AddUIPage({ id = Constants.UITypeIds.ActivityNightCatDialog, parameters = {activityId = self:GetActivityId(), questId = id, clearChapter = clearChapter, unlockChapters = unlockChapters}})
        FightPreWarMgr:GetInstance():FightEnter(id, {activityUuid = activityId})
    end
end

---播放剧情
function ActivityNightCatMgr:PlayPlot(vo, endCb)
    if not vo then
        return
    end
    if self._isPlayPlot then
        return
    end
    self._isPlayPlot = true
    local plotIds = CfUtils.Split(vo.plotId)
    if not plotIds then
        GameUtils.Toast(localize("该关卡没有剧情参数"))
        self._isPlayPlot = false
        return
    end
    
    self._curPlotIndex = 1
    self:PlayingPlot(plotIds, vo, endCb)
end



---剧情播放中
function ActivityNightCatMgr:PlayingPlot(plotIds, vo, endCb)
    local co = cs_coroutine.start(function()
        ::start::
        local wait = true
        local lastDialog = UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.ActivityNightCatDialog)
        ChapterUtils.ProcessChapter(checkNumber(plotIds[self._curPlotIndex]), function(go)
            if lastDialog then
                lastDialog.transform.localPosition = Vector3(9999, 9999, 9999)
            end
            URPCameraController:SetMainCameraActive(false)
            UINavigationBarRoot.Instance:SetActive(false)
            self._plotGo = go
        end, function()
            --所有的播完结束
            if lastDialog then
                lastDialog.transform.localPosition = Vector3(0, 0, 0)
            end
            URPCameraController:SetMainCameraActive(true)
            UINavigationBarRoot.Instance:SetActive(true)
            wait = false
        end)

        while wait do
            coroutine.yield()
        end

        KTool.SafeDelete(self._plotGo)

        --dispose
        coroutine.yield()

        if self._curPlotIndex >= table.count(plotIds) then
            GameUtils.PlayMainBGM()
            if endCb then
                endCb()
            end

            self._isPlayPlot = false
        else
            self._curPlotIndex = self._curPlotIndex + 1
            goto start
        end
    end)
end

