---获取章节剧情数据
---@param chapterId integer 章节id
function ActivityNightCatMgr:GetChapterPlotData(chapterId)
    local chapterPlotData = {}
    local questChapterVo = CfUtils.GetCf(AutoIds.IdSetting2733, "NightCatPlotVo", true)
    for _, v in ipairs(questChapterVo) do
        if checkInt(v.chapter) == checkInt(chapterId) then
            v.state = self:GetPlotState(v.id)
            table.insert(chapterPlotData, v)
        end
    end
    table.sort(chapterPlotData, function(a, b)
        return a.id < b.id
    end)
    return chapterPlotData
end

---获取剧情状态
---@param plotId integer 剧情id
---@return integer ActivityNightCatConstants.ChapterState
function ActivityNightCatMgr:GetPlotState(plotId)
    local questChapterVo = CfUtils.GetCfVo(AutoIds.IdSetting2733, "NightCatPlotVo", plotId)
    if not questChapterVo then return end

    local comp = self:GetNightCatComponent()
    local questId = self:GetPlotInfoByChapterId(questChapterVo.chapter)
    local unlockPlotInfo = comp:GetUnlockPlotInfo()
    local lastPlotId = nil
    if questId > 0 then
        lastPlotId = self:GetPlotIdByQuestId(questId)
    end
    
    if lastPlotId and checkInt(plotId) <= lastPlotId then
        return ActivityNightCatConstants.ChapterState.FINISH
    else
        return checkInt(unlockPlotInfo[tostring(plotId)]) + 1
    end
end


