function ActivityNightCatMgr:GetPlotIdByQuestId(questId)
    local questChapterVo = CfUtils.GetCf(AutoIds.IdSetting2733, "NightCatPlotVo", true)
    for _, v in ipairs(questChapterVo) do
        if checkInt(v.regionId) == checkInt(questId) then
            return checkInt(v.id)
        end
    end
    print("无效的暗夜猫剧情关卡id")
end



