---关卡通关后可解锁的章节
---@param questId integer 关卡id
---@return integer, integer[]
function ActivityNightCatMgr:GetQuestClearUnlockChapter(questId)
    local plotId = self:GetPlotIdByQuestId(questId)
    local plotVo = CfUtils.GetCfVo(AutoIds.IdSetting2733, "NightCatPlotVo", plotId)
    local clearChapter = nil
    local unlockChapters = {}
    local storyId = self:GetPrologueStoryId()
    -- 序章不处理
    if plotId == storyId then return clearChapter, unlockChapters end
    
    -- 判断是否为章节最后一关
    if checkInt(plotVo.endFlag) ~= 1 then return clearChapter, unlockChapters end

    local plotState = self:GetPlotState(plotId)
    -- 判断是否为关卡首次通关
    if plotState ~= ActivityNightCatConstants.ChapterState.UNLOCK then return clearChapter, unlockChapters end
    
    clearChapter = checkInt(plotVo.chapter)

    local chapterVo = CfUtils.GetCf(AutoIds.IdSetting2735, "NightCatQuestChapterVo", true)
    
    for _, v in ipairs(chapterVo) do
        if checkInt(v.activityId) == checkInt(plotVo.activityId) then
            if tostring(v.unlockChapter) ~= '0' and string.find(tostring(v.unlockChapter), tostring(plotVo.chapter)) then
                -- 找到此关卡解锁的章节
                local unlockChapterList = string.split2(v.unlockChapter, ";")
                local isUnlock = true
                for _, value in ipairs(unlockChapterList) do
                    if checkInt(value) ~= checkInt(plotVo.chapter) then
                        local state = self:GetChapterState(value)
                        if state ~= ActivityNightCatConstants.ChapterState.FINISH then
                            isUnlock = false
                            break
                        end
                    end
                end
                if isUnlock then
                    table.insert(unlockChapters, v.id)
                end
            end
        end
    end
    return clearChapter, unlockChapters
end

